package cn.kaoyan.assistant;
import java.util.concurrent.*;
public class WorkQueuesTest {public static void main(String[] a)throws Exception{WorkQueues q=new WorkQueues();CountDownLatch started=new CountDownLatch(3),release=new CountDownLatch(1),local=new CountDownLatch(1);for(int i=0;i<3;i++)q.network.execute(()->{started.countDown();try{release.await();}catch(InterruptedException ignored){}});try{if(!started.await(2,TimeUnit.SECONDS))throw new AssertionError("network not started");q.local.execute(local::countDown);if(!local.await(300,TimeUnit.MILLISECONDS))throw new AssertionError("blocked network must not starve local storage");System.out.println("Local disk work completes while three concurrent classification workers are blocked");}finally{release.countDown();q.close();}}}
